import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Browser verification","description":"What the automated documentation browser review checks and what it cannot prove.","frontmatter":{"title":"Browser verification","description":"What the automated documentation browser review checks and what it cannot prove."},"headers":[],"relativePath":"reference/browser-review.md","filePath":"reference/browser-review.md","lastUpdated":1794433168000}'),o={name:"reference/browser-review.md"};function s(n,e,c,d,h,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="review-the-rendered-site" tabindex="-1">Review the rendered site <a class="header-anchor" href="#review-the-rendered-site" aria-label="Permalink to &quot;Review the rendered site&quot;">​</a></h1><p>The <strong>Documentation browser review</strong> workflow builds VitePress and serves its static output over isolated loopback HTTP in CI. It uses the runner&#39;s installed Chrome and records the exact browser version in the receipt. There is no provider credential or new application dependency.</p><h2 id="automated-checks" tabindex="-1">Automated checks <a class="header-anchor" href="#automated-checks" aria-label="Permalink to &quot;Automated checks&quot;">​</a></h2><p>Seven routes are inspected at desktop and narrow-screen sizes and in dark mode: homepage, vision, walkthrough, design, build, glossary and twelve-factor guidance. Each must have one H1, a source-revision marker and no page-level horizontal overflow.</p><p>The review also opens local search, checks results remain under the repository path, opens mobile navigation and rejects reported JavaScript exceptions. It captures screenshots and a JSON receipt in the <code>documentation-browser-review</code> artifact.</p><h2 id="inspect-the-artifact" tabindex="-1">Inspect the artifact <a class="header-anchor" href="#inspect-the-artifact" aria-label="Permalink to &quot;Inspect the artifact&quot;">​</a></h2><p>Review the home screenshots in desktop, mobile and dark layouts and the vision-page screenshot. Automated layout checks do not judge whether a visual hierarchy or reading path is useful. Record that human/assistant inspection separately.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>This is not a Safari test, a screen-reader audit, production HTTPS validation or universal accessibility certification. The runner browser is recorded, not claimed to be identical across future runs. Static source/build checks, browser review and live Pages publication are different gates.</p><p>The <a href="./../project/setup">publishing workflow</a> separately verifies public responses and the deployed revision. <a href="./documentation-map">Documentation map</a>.</p>',10)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
